  function parseRule(rule) {   // 'day' · 'day3' · 'm780@0' · 'day@840' · 'at:6-7,14-15' · 'month' · 'any' · 'obelisk' · 'dec' / 'nov2' (a month, and how many a day); '!3,13' = shut in those hours (NST)
    const [r, shut] = String(rule).split('!');
    const closed = shut ? shut.split(',').map(Number) : null;
    let m;
    if ((m = /^day(\d*)(?:@(\d+))?$/.exec(r))) return { kind: 'day', max: +m[1] || 1, dayStart: m[2] !== undefined ? +m[2] : null, closed };
    if ((m = /^m(\d+)(?:@(\d+))?$/.exec(r))) return { kind: 'every', mins: +m[1], dayStart: m[2] !== undefined ? +m[2] : null, closed };
    if ((m = /^at:(.+)$/.exec(r))) return { kind: 'at', wins: m[1].split(',').map((w) => w.split('-').map(Number)) };
    if ((m = /^(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)(\d*)$/.exec(r))) return { kind: 'day', max: +m[2] || 1, dayStart: null, closed, month: ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'].indexOf(m[1]) + 1 };
    return { kind: r, closed };   // month · any · obelisk
  }
