      const a = el.querySelector('.boardDesc a[href*="board="]'), id = a ? Number((/board=(\d+)/.exec(a.getAttribute('href')) || [])[1]) : 0;
      if (!id) continue;
      const recent = el.querySelector('.recent'), when = reClean(recent && recent.textContent), mins = nbAgoMins(when);
      if (mins <= 60) lively++;
      el.classList.add('bnp-nb-board');
      el.classList.toggle('bnp-nb-hot', mins <= 10);
      if (recent && !when) recent.classList.add('is-none');
      el.dataset.bnpBoard = String(id);
      el.dataset.cat = cat;
      const num = (sel) => Number(reClean((el.querySelector(sel) || {}).textContent).replace(/[^\d]/g, '')) || 0, topics = num('.topics'), posts = num('.comments');
      const foot = document.createElement('div');   // (its numbers, in a strip at its foot: Neopets' own three columns stay, out of sight)
      foot.className = 'bnp-nbbf';
      foot.setAttribute('data-bnp', 'nbbf');
      foot.innerHTML = `<span><b>${topics.toLocaleString()}</b> topic${topics === 1 ? '' : 's'}</span><span><b>${posts.toLocaleString()}</b> post${posts === 1 ? '' : 's'}</span>${when ? (mins <= 10 ? `<span class="is-when is-hot">${esc(when)}</span>` : `<span class="is-when">latest ${esc(when)}</span>`) : '<span class="is-when">no posts yet</span>'}`;
      el.append(foot);
      const star = document.createElement('button');
      star.type = 'button';
      star.className = 'bnp-nb-star';
