    const sets = [n(all) ? chip('*', 'Every theme', all, !own) : '', ...Object.keys(by).sort((x, y) => nbcThemeName(x).localeCompare(nbcThemeName(y))).map((t) => chip(t, nbcThemeName(t), by[t], t === k))].filter(Boolean);
