    const name = nbcVar(p), els = [document.documentElement, nbc.box.firstElementChild, nbc.probe].filter(Boolean);
    if (!cp.live) { cp.live = true; cp.was = els.map((el) => [el, el.style.getPropertyValue(name), el.style.getPropertyPriority(name)]); }
