    if (!u || !/\/neoboards\/avatars\/[^/?#]+\.(gif|png|jpe?g|webp)$/i.test(pic)) return;
    (nfSee.q = nfSee.q || new Map()).set(u, pic);
    clearTimeout(nfSee.t);
