    const pic = [...$$('#usercollections img[src*="/neoboards/avatars/"]'), ...$$('#userinfo img[src*="/neoboards/avatars/"]')].map((i) => fullUrl(i.getAttribute('src')))
      .find((x) => /\/neoboards\/avatars\/[^/?#]+\.(gif|png|jpe?g|webp)$/i.test(x) && !/\/default\.gif$/i.test(x));
    if (!u || !pic) return;
    const d = nfData();
