    const stopAt = (n) => n.nodeType === 1 && !popup(n) && (/^(FORM|TABLE|DIV|CENTER|UL|OL)$/.test(n.tagName) || !!n.querySelector('form, table, input, select, textarea, img'));   // (the page's own work starts: its notes are only what comes before)
