    head.querySelector('[data-nmhelp]').addEventListener('click', (e) => { intro.hidden = !intro.hidden; e.currentTarget.setAttribute('aria-expanded', String(!intro.hidden)); });
    const tabs = head.querySelector('[data-g="nmtabs"]');
