    if (/login/i.test(new URL(r.url).pathname)) throw new Error('signed out');
    const p = get('pets', null) || { list: [], at: 0 };
    p.list = Array.isArray(p.list) ? p.list : [];
    p.list.forEach((x) => { x.active = x.name === name; });
