        out.push(`<div class="bqr-note is-sick"><span class="bqr-note-ic" style="background-image:url('${esc(cssUrl(n.icon))}')"></span><div><b>${esc(p.name)} has ${esc(d && d.name ? d.name : 'a disease')}</b>${cure || `<span>${n.html}</span>`}</div></div>`);
