  const shopSortKey = (id) => shopShort(id).replace(/^The\s+/i, '').toLowerCase();   // (A to Z by the name on its tile: The Bakery under B)
  const shopsSorted = (ids, how) => (how === 'id' ? ids.slice().sort((a, b) => a - b) : how === 'az' ? ids.slice().sort((a, b) => shopSortKey(a).localeCompare(shopSortKey(b))) : ids);
