  const SVG_FOLD = (down) => `<svg viewBox="0 0 16 16" aria-hidden="true"><path d="${down ? 'M3.5 6l4.5 4.5L12.5 6' : 'M3.5 10L8 5.5l4.5 4.5'}" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
