      win.innerHTML = `<div class="popup-header__2020 bnp-hub-head"><h3>Your shops</h3><button type="button" class="popup-exit button-default__2020 button-red__2020 bnp-sdock-x bnp-pick-x" data-pk="x" title="Done" aria-label="Done"><div class="popup-exit-icon"></div></button><div class="popup-header-pattern__2020"></div></div>
        <div class="bnp-go-box"><span class="bnp-go-glass" aria-hidden="true"></span><input type="text" class="bnp-go-q" data-pk="q" placeholder="Narrow it down: food, petpet, Brightvale, 13…" autocomplete="off" spellcheck="false"><span class="bnp-pick-sort" role="group" aria-label="Order"><button type="button" data-pk-sort="az" title="By name">A–Z</button><button type="button" data-pk-sort="id" title="By shop number, lowest first">1–9</button></span></div>
        <div class="bnp-pick-grid" role="group" aria-label="Neopia’s shops"></div>
        <div class="bnp-go-foot bnp-pick-foot"><span data-pk="n"></span><span class="bnp-pick-tools"><button type="button" class="bnp-linkbtn" data-pk="none">None</button><button type="button" class="button-default__2020 button-yellow__2020 bnp-small" data-pk="x">Done</button></span></div>`;
      document.body.append(veil, win);
