    const ids = shopsSorted(Object.keys(TAB_SHOPS), d.pickSort === 'id' ? 'id' : 'az');
    const shown = num ? ids.filter((id) => id.startsWith(raw)).sort((a, b) => (b === raw) - (a === raw))
      : q ? ids.filter((id) => goNorm(`${TAB_SHOPS[id]} ${SHOP_KIND[id] || ''}`).includes(q) || goName(goNorm(TAB_SHOPS[id]), q, q.replace(/ /g, ''), false) > 0) : ids;
    shopPick.grid.innerHTML = shown.map((id) => { const on = list.includes(id); return `<button type="button" class="bnp-pick-tile${on ? ' is-on' : ''}" data-pick="${esc(id)}" aria-pressed="${on}" title="${esc(TAB_SHOPS[id])}${SHOP_KIND[id] ? ` (${esc(SHOP_KIND[id])})` : ''} · shop ${esc(id)}"><span class="bnp-sdock-pic" style="${esc(icoCss(`${NPI}shopkeepers/w${id}.gif`))}"></span>${byNo ? `<span class="bnp-shop-no">${esc(id)}</span>` : ''}<span class="bnp-sdock-name">${esc(shopShort(id))}</span><span class="bnp-pick-check" aria-hidden="true">✓</span></button>`; }).join('') || `<p class="bnp-go-none">${num ? 'No shop has that number.' : 'No shop by that name.'}</p>`;
