      const i = Number(h.getAttribute('data-avatar-id')), img = h.querySelector('img'), f = avFile(img ? img.getAttribute('src') : '');
      if (!i || !f) continue;
      const body = doc.querySelector(`.panel-body[data-avatar-id="${i}"] .col-md-8`) || doc.querySelector(`.panel-body[data-avatar-id="${i}"]`);
