    const read = (g) => [...g.querySelectorAll('.settings-av')].map((el) => { const img = el.querySelector('img'); return [avFile(img ? img.getAttribute('src') : ''), (el.id || '').replace(/Avvie$/, ''), reClean((img && img.getAttribute('alt')) || el.textContent).slice(0, 80)]; }).filter((x) => x[0]);
    const mine = [], everyone = [];
