      if (old) Object.assign(old, { pattern, title, icon }); else T.rules.unshift({ id: 'r' + uid(), pattern, title, icon });
      tabEdit = null;
      tabsChanged(old ? 'Saved' : 'Added: it comes first', () => { T.rules = before; tabsChanged(); });
      return;
