        <label class="bnp-f"><span>Its picture</span><select data-feat="profileIcon"><option value="profile"${f.profileIcon === 'profile' ? ' selected' : ''}>Your theme’s profile icon</option><option value="pet"${f.profileIcon === 'pet' ? ' selected' : ''}>Your active pet</option></select></label>
